def _silu(x):
  return x / (1.0 + np.exp(-np.clip(x, -30.0, 30.0)))


def score_trajectory_hybrid_nn(feat_14):
  """Return (nn_prob, confidence_pct) for a 14-element trajectory feature vector."""
  xn = (np.asarray(feat_14, dtype=np.float64) - FEAT_MEAN) / FEAT_STD
  h1 = _silu(W1 @ xn + B1)
  h2 = _silu(W2 @ h1 + B2)
  logit = float((W3 @ h2 + B3 + W_SKIP @ xn)[0])
  p_nn = 1.0 / (1.0 + math.exp(-max(-30.0, min(30.0, logit))))
  if p_nn < 0.25:
    conf = min(99.9, 35.0 * ((p_nn / 0.25) ** 0.52))
  else:
    conf = min(99.9, 35.0 + 64.9 * (((p_nn - 0.25) / 0.75) ** 0.65))
  return p_nn, conf
